-- Verify CPF R6 V106 persistent data-quality provider schema
DECLARE v_count NUMBER; BEGIN
 SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME='CPF_DATA_QUALITY_RULE' AND COLUMN_NAME='PARAMETERS_PAYLOAD'; IF v_count<>1 THEN RAISE_APPLICATION_ERROR(-20071,'PARAMETERS_PAYLOAD missing'); END IF;
 SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME='CPF_DATA_QUALITY_QUARANTINE' AND COLUMN_NAME='VIOLATION_PAYLOAD'; IF v_count<>1 THEN RAISE_APPLICATION_ERROR(-20072,'VIOLATION_PAYLOAD missing'); END IF;
 SELECT COUNT(*) INTO v_count FROM USER_TABLES WHERE TABLE_NAME='CPF_DATA_QUALITY_OPERATION'; IF v_count<>1 THEN RAISE_APPLICATION_ERROR(-20073,'CPF_DATA_QUALITY_OPERATION missing'); END IF;
END;
/
SELECT COUNT(*) AS persistent_dq_operations FROM CPF_DATA_QUALITY_OPERATION;
